import math


def round_half_even(x):
    floor_x = math.floor(x)
    diff = x - floor_x
    if diff < 0.5:
        return floor_x
    if diff > 0.5:
        return floor_x + 1
    # exactly halfway: round to even
    return floor_x if floor_x % 2 == 0 else floor_x + 1

